/* eslint-disable jsx-a11y/no-noninteractive-element-interactions */


import { useContext, useEffect, useMemo, useState } from "react";
import TabContext from "@mui/lab/TabContext";
import TabList from "@mui/lab/TabList";
import { Pagination, Skeleton, Tab } from "@mui/material";
import TabPanel from "@mui/lab/TabPanel";
import DeleteIcon from "@mui/icons-material/Delete";
import InputLabel from '@mui/material/InputLabel';
import GenerateToastConfig from 'src/components/toast-config/GenerateToastConfig';
import { IMAGE_URL } from "src/utils/config"
import { useMyContext } from "src/pages/provider";
import styles from "./gallery.module.scss";
import { PhotosIcon } from "./svg";
import { axios } from '../../utils/axios';
import RightDrawer from './drawer';

const limit = 12;

const ActionsIcon = (props) => (
  <svg
    viewBox="0 0 16 16"
    className={props.className}
    style={props.style}
    width={props.width}
    height={props.height}
    fill={props.color}
  >
    <path d="M3 6a2 2 0 1 0 0 4 2 2 0 0 0 0-4zm5 0a2 2 0 1 0 0 4 2 2 0 0 0 0-4zm5 0a2 2 0 1 0 0 4 2 2 0 0 0 0-4z" />
  </svg>
);

const ArrayMove = (arr, oldIndex, newIndex) => {
  const cloneArr =[...arr];
  cloneArr.splice(newIndex, 0, cloneArr.splice(oldIndex, 1)[0]);
  return cloneArr;
};

export default function InputGallery({ fnc, imageCount, selectedImages, category, fncData, mode='value' }) {
  const [openDrawer, setOpenDrawer] = useState({ open: false, drawer: "" });
  const [dropdownVisible, setDropdownVisible] = useState(null);
  const [data, setData] = useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const [isLoading, setLoading] = useState(false);
  const { i18 } = useMyContext();
  const [images, setImages] = useState([]);
  const [value, setValue] = useState("local");
  const [page, setPage] = useState(1);
  const handleChangePagination = (event, value) => {
    setPage(value);
  };
  const Total = Math.ceil(totalCount / limit);
  const handleChange = (event, newValue) => {
    setValue(newValue);
  };

  const toggleDropdown = (index) => {
    if (dropdownVisible == null) {
      setDropdownVisible(index);
    } else {
      setDropdownVisible(null);
    }
  };

  // useEffect(()=>{
  //   setImages(selectedImages)
  // },[selectedImages])

  const nonSelectable = useMemo(()=>{
    return selectedImages.reduce((acc, item) => {
      acc[item.ImageId] = true;
      return acc;
    }, {});
  },[selectedImages])

  const handleImage = (index, imagePath, id) => {
    if(nonSelectable[id]) {
      return;
    }
    setImages((prevImages) => {
      const existingImageIndex = prevImages.findIndex(
        (item) => item.ImageId === id
      );
      if (existingImageIndex !== -1) {
        return prevImages.filter((_, i) => i !== existingImageIndex);
      }
      if(mode==='value') {
        return [{ index, imagePath, ImageId: id }];
      }
      
        const newImages = [...prevImages, { index, imagePath, ImageId: id }];
        const len = newImages.length + selectedImages.length;
        if(len <= imageCount) {
          return newImages;
        } 
          const deleteCount = imageCount - selectedImages.length;
          return newImages.slice(-deleteCount);
    });
  };

  const fetchData = async (page) => {
    try {
    const data = await axios.get(`module/gallery/images?collection=${category}&_page=${page}&_limit=${limit}`);
    if(Array.isArray(data?.data?.data?.galleryImage)) {
      setData(data?.data?.data?.galleryImage);
      setTotalCount(data?.data?.totalCount)
    }
  } catch(err) {
    console.log('err', err);
  }
  }
  useEffect(() => {
    if (value === "gallery") {
      fetchData(page)
    }

  }, [value, page]);
  const handleImageChange = (e) => {
    const files = e.target.files;
    const formData = new FormData();
    formData.append("collection", category);

    for (let i = 0; i < files.length; i+=1) {
      // imagesArray.push(files[i]);
      formData.append("images[]", files[i]);
    }
    uploadImages(formData);
  };

  const uploadImages = async (formData) => {
    try {
      const response = await axios.post(`module/gallery/images`, formData);
      // const response = await dispatch(SetImageGallery(formData));
      if (response.data.status) {
        setValue("gallery");
      }
    } catch (error) {
      console.error("Error uploading images:", error);
    }
  };

  const DeleteImages = async (e) => {
    e.preventDefault();
    const str = images.map((item) => item.ImageId).join(",");
    const response = await axios.delete(
      `module/gallery/images?imageIds=${str}`
    );
    if (response.data.status) {
      fetchData(1);
      setPage(1);
        GenerateToastConfig(response.data.message, 'success')
    } else {
      GenerateToastConfig(response.message, 'error')
    }
  };

  const handleImageDelete = (deleteindex) => {
    const images = selectedImages.filter((item,index)=>index!==deleteindex);
    fnc(images, fncData);
    setDropdownVisible(null);
  }

  const handleOptionSelect = (option, index) => {
    const arr = ArrayMove(selectedImages, index, index + option);
    fnc(arr, fncData)
    setDropdownVisible(null);
  };


  return (<>
    <RightDrawer
        open={openDrawer.open}
        onClose={() => setOpenDrawer({ open: false, drawer: "" })}
      >
    <div className={`${styles.gallerymodal}`}>
      <TabContext value={value}>
        <TabList
          onChange={handleChange}
          aria-label="lab API tabs example"
          sx={{
            "& .MuiTabs-indicator": {
              backgroundColor: "var(--search-button-color) !important",
            },
          }}
        >
          <Tab
            label="Local"
            value="local"
            sx={{
              "&.Mui-selected": {
                color: "black",
                fontWeight: "600",
              },
            }}
          />
          <Tab
            label="Gallery"
            value="gallery"
            sx={{
              "&.Mui-selected": {
                color: "black",
                fontWeight: "600",
              },
            }}
          />
        </TabList>
        <TabPanel value="local" sx={{ padding: "0px", marginTop: "30px" }}>
          <section className={`${styles.step8}`}>
            {isLoading ? (
              <div className="d-flex justify-content-center align-items-center">
                {/* <Loader /> */}
              </div>
            ) : (
              <label
                className={`d-block ${styles.custom_fileupload}`}
                htmlFor="imageUpload"
              >
                <div className={`${styles.upload_sec} h-100 checkbox`}>
                  <div className={`${styles.photos_upload} mt-5`}>
                    <div>
                      <PhotosIcon
                        width="64"
                        height="64"
                        style={{
                          display: "block",
                          fill: " currentcolor",
                        }}
                      />
                      <div className={`pt-2`}>
                        <label htmlFor="imageUpload">
                          <input
                            type="file"
                            id="imageUpload"
                            className={`${styles.imageUpload}`}
                            onChange={handleImageChange}
                            multiple
                            accept="image/*"
                          />
                          {i18?.ADDPHOTO?.UPLOAD || "Upload from your device"}
                        </label>
                      </div>
                    </div>
                  </div>
                </div>
              </label>
            )}
          </section>
        </TabPanel>
        <TabPanel value="gallery" sx={{ padding: "0px", marginTop: "30px" }}>
          <>
            {value === "gallery" && (
              <div
                className={`
            ${styles.buttonGallery} 
            d-flex justify-content-end`}
              >
                <div className="d-flex gap-3 align-items-center">
                  <div>
                    <button
                      style={{
                        backgroundColor:
                          images.length > 0
                            ? "#2065D1"
                            : "#D8D2C2",
                        border:
                          images.length > 0
                            ? "1px solid #2065D1"
                            : "1px solid #D8D2C2",
                      }}
                      disabled={images.length === 0}
                      onClick={(e) => {
                        e.preventDefault();
                        fnc([...images,...selectedImages], fncData);
                        setOpenDrawer((prev)=>({...prev, open: false}));
                      }}
                    >
                      Upload
                    </button>
                  </div>
                  <button
                    disabled={images.length === 0}
                    onClick={DeleteImages}
                    style={{
                      backgroundColor:
                        images.length > 0
                          ? "#FF5A60"
                          : "#D8D2C2",
                      border:
                        images.length > 0
                          ? "1px solid #FF5A60"
                          : "1px solid #D8D2C2",
                      padding: "10px",
                      borderRadius: "5px",
                    }}
                  >
                    <DeleteIcon style={{ color: "#fff" }} />
                  </button>
                </div>
              </div>
            )}
            {data.length > 0 ? (
              <div className={`${styles.section}`}>
                {isLoading ? (
                  <div className="d-flex gap-3">
                    <Skeleton
                      variant="rectangular"
                      width={210}
                      height={200}
                      sx={{ borderRadius: "8px" }}
                    />
                    <Skeleton
                      variant="rectangular"
                      width={210}
                      height={200}
                      sx={{ borderRadius: "8px" }}
                    />
                    <Skeleton
                      variant="rectangular"
                      width={210}
                      height={200}
                      sx={{ borderRadius: "8px" }}
                    />
                    <Skeleton
                      variant="rectangular"
                      width={210}
                      height={200}
                      sx={{ borderRadius: "8px" }}
                    />
                    <Skeleton
                      variant="rectangular"
                      width={210}
                      height={200}
                      sx={{ borderRadius: "8px" }}
                    />
                  </div>
                ) : (
                  Array.isArray(data) &&
                  data.map((item, index) => {
                    const isSelected = images.some(
                      (selectedItem) => selectedItem.ImageId === item._id
                    );
                    return (
                      <div
                        key={index}
                        role={nonSelectable[item._id] ?'':'button'}
                        aria-hidden="true"
                        onClick={() =>
                          handleImage(index, item?.path, item?._id)
                        }
                      >
                        <div className={styles.relative}>
                          <img
                            src={IMAGE_URL + item.path}
                            alt="img"
                            className={`${
                              nonSelectable[item._id] ? styles?.noSelect :
                              isSelected ? styles?.imgSelect : styles.img
                            }`}
                          />
                          {!nonSelectable[item._id] &&
                          <div className={styles.absolute}>
                            {isSelected ? (
                              <img
                                src={`/assets/icons/circled-check.svg`}
                                alt="img"
                                width={25}
                                height={25}
                              />
                            ) : (
                              <img
                                src={`/assets/icons/circle.svg`}
                                alt="img"
                                width={25}
                                height={25}
                              />
                            )}
                          </div>}
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            ) : (
              <section className={`${styles.step8}`}>
                <div className={`${styles.upload_sec} h-100 checkbox`}>
                  <div className={`${styles.photos_upload} mt-5`}>
                    <div>
                      <PhotosIcon
                        width="64"
                        height="64"
                        style={{
                          display: "block",
                          fill: " currentcolor",
                        }}
                      />
                      <h4>Gallery is empty</h4>
                      <button
                        style={{
                          padding: "10px",
                          borderRadius: "8px",
                          border: "1px solid  var(--search-button-color)",
                          backgroundColor: " var(--search-button-color)",
                          color: "#fff",
                        }}
                        onClick={(e) => {
                          e.preventDefault();
                          setValue("local")
                        }}
                      >
                        Upload
                      </button>
                    </div>
                  </div>
                </div>
              </section>
            )}

            <div className={`${styles.footer}`}>
              <Pagination
                count={Total}
                page={page}
                onChange={handleChangePagination}
                sx={{
                  "& .Mui-selected": {
                    backgroundColor: "#2065D1 !important",
                    color: "#fff",
                  },
                }}
              />
            </div>
          </>
        </TabPanel>
      </TabContext>
    </div>
    </RightDrawer>
    <div className='d-flex flex-column gap-1'>
                        <InputLabel sx={{ color: "#2B3343" }} id="demo-simple-select-label">{i18?.FORM?.ICON || 'Icon'}</InputLabel>

                        {mode==="value" ? <button
      style={{ border: "1px solid #d3d6d8", borderRadius: "8px", display: "flex", justifyContent: "center", alignItems: "center", width: "100px", height: "100px" }}
      onClick={(e)=>{ 
        e.preventDefault();
        setOpenDrawer((prev)=>({...prev, open: true}));
      }}
      >
      {
        selectedImages.length>0 ?
            <img src={`${IMAGE_URL}${selectedImages[0]}`}alt="" className="" />
          :
          "+"
      }
    </button>: <div className="d-flex gap-3">{selectedImages.map((item,f)=>(<div
      className={styles.photos_upload}
      style={{
        backgroundImage: `url(${IMAGE_URL}${item.imagePath})`
      }}
      // onClick={(e)=>{ 
      //   e.preventDefault();
      //   setOpenDrawer((prev)=>({...prev, open: true}));
      // }}
      >
    

        <button
                          className={`${styles.action_icon} ms-auto`}
                          onClick={(e) => {
                            e.preventDefault();
                            e.stopPropagation();
                            toggleDropdown(f)
                          }}
                        >
                          <span>
                            <ActionsIcon
                              width="16"
                              height="16"
                              style={{
                                display: "block",
                                fill: "var(--footer-text-color)",
                              }}
                            />
                          </span>
                        </button>
                        {dropdownVisible === f ? (
                          <div className={`${styles.dropdown}`}>
                            <ul>
                            {selectedImages.length > 1 && f > 0 && (
                                <li
                                  style={{ color: "var(--text-color)" }}
                                  onClick={() => handleOptionSelect(-1, f)}
                                >
                                  {i18?.ADDPHOTO?.MOVEBACKWARDS ||
                                    "Move backwards"}
                                </li>
                              )}
                              {selectedImages.length > 1 && f < (selectedImages.length -1) && (
                                <li
                                  style={{ color: "var(--text-color)" }}
                                  onClick={() => handleOptionSelect(1, f)}
                                >
                                  {i18?.ADDPHOTO?.MOVEFORWARDS ||
                                    "Move forwards"}
                                </li>
                              )}
                              {
                                <li
                                  style={{ color: "var(--text-color)" }}
                                  onClick={() =>{
                                    handleImageDelete(f)
                                  }
                                  }
                                >
                                  {i18?.ADDPHOTO?.DELETE || "Delete"}
                                </li>
                              }
                            </ul>
                          </div>
                        ) : null}
    </div>))}
{imageCount - selectedImages.length > 0 && Array.from({ length: imageCount - selectedImages.length }).map((item)=>(
  <button
      style={{ border: "1px solid #d3d6d8", borderRadius: "8px", display: "flex", justifyContent: "center", alignItems: "center", width: "100px", height: "100px" }}
      onClick={(e)=>{ 
        e.preventDefault();
        setOpenDrawer((prev)=>({...prev, open: true}));
      }}
      >
      {
          "+"
      }
    </button>
))}
    

    </div>}
                      </div>
    </>
  );
}
